<?php
namespace App\Features\Post\Services;
use App\Features\Post\Models\Post;use App\Models\User;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class PostService {public function create(User $user,array $data):Post{return DB::transaction(fn()=> $user->posts()->create($this->payload($data)));}public function update(Post $post,array $data):Post{return DB::transaction(function()use($post,$data){$payload=$this->payload($data);unset($payload['slug']);if($payload['title']!==$post->title)$payload['slug']=Post::uniqueSlug($payload['title'],$post->id);$post->update($payload);return $post->refresh();});}private function payload(array $data):array{$published=(bool)($data['is_published']??false);return ['title'=>$data['title'],'slug'=>Post::uniqueSlug($data['title']),'category'=>$data['category'],'excerpt'=>$data['excerpt']??Str::limit(strip_tags($data['content']),180),'content'=>$data['content'],'is_published'=>$published,'published_at'=>$published?now():null];}public function toggle(Post $post):Post{$published=!$post->is_published;$post->update(['is_published'=>$published,'published_at'=>$published?now():null]);return $post->refresh();}}
